[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>DeployCloud Blog — Discover the latest in web development</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #FAFAFA;
      --bg-card: #FFFFFF;
      --bg-hover: #F4F4F5;
      --border: #E4E4E7;
      --border-strong: #D1D5DB;
      --text-primary: #171717;
      --text-secondary: #52525B;
      --text-muted: #71717A;
      --accent: #0072F5;
      --accent-hover: #005ED4;
      --accent-light: #EFF6FF;
      --accent-subtle: rgba(0, 114, 245, 0.08);
      --navy: #0F172A;
      --font: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      --radius: 10px;
      --radius-sm: 6px;
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
      --shadow: 0 4px 12px rgba(0,0,0,0.06), 0 2px 4px rgba(0,0,0,0.04);
      --shadow-lg: 0 8px 24px rgba(0,0,0,0.08), 0 4px 8px rgba(0,0,0,0.04);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      background: var(--bg);
      color: var(--text-primary);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }

    /* ─── NAV ─────────────────────────────────────────────────── */
    .nav-wrapper {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(250,250,250,0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
    }

    nav {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
      height: 60px;
      display: flex;
      align-items: center;
      gap: 0;
    }

    .nav-logo {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 15px;
      font-weight: 700;
      color: var(--text-primary);
      letter-spacing: -0.3px;
      margin-right: 32px;
      flex-shrink: 0;
    }

    .nav-logo-icon {
      width: 28px;
      height: 28px;
      background: var(--navy);
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .nav-logo-icon svg { width: 16px; height: 16px; }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 2px;
      flex: 1;
    }

    .nav-link {
      font-size: 13.5px;
      font-weight: 500;
      color: var(--text-secondary);
      padding: 6px 12px;
      border-radius: var(--radius-sm);
      transition: all 0.15s;
      cursor: pointer;
      white-space: nowrap;
      display: flex;
      align-items: center;
      gap: 4px;
      position: relative;
    }

    .nav-link:hover { color: var(--text-primary); background: var(--bg-hover); }

    .nav-link svg { width: 12px; height: 12px; transition: transform 0.15s; }
    .nav-link:hover svg { transform: rotate(180deg); }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-left: auto;
    }

    .btn {
      font-family: var(--font);
      font-size: 13.5px;
      font-weight: 600;
      padding: 7px 16px;
      border-radius: var(--radius-sm);
      border: none;
      cursor: pointer;
      transition: all 0.15s;
      display: inline-flex;
      align-items: center;
      gap: 6px;
      white-space: nowrap;
    }

    .btn-ghost {
      background: transparent;
      color: var(--text-secondary);
    }
    .btn-ghost:hover { background: var(--bg-hover); color: var(--text-primary); }

    .btn-outline {
      background: transparent;
      color: var(--text-primary);
      border: 1px solid var(--border-strong);
    }
    .btn-outline:hover { background: var(--bg-hover); }

    .btn-primary {
      background: var(--text-primary);
      color: #fff;
    }
    .btn-primary:hover { background: #333; }

    .btn-accent {
      background: var(--accent);
      color: #fff;
    }
    .btn-accent:hover { background: var(--accent-hover); }

    /* ─── DROPDOWN ────────────────────────────────────────────── */
    .dropdown-container { position: relative; }

    .dropdown-menu {
      position: absolute;
      top: calc(100% + 8px);
      left: 50%;
      transform: translateX(-50%);
      background: #fff;
      border: 1px solid var(--border);
      border-radius: var(--radius);
      box-shadow: var(--shadow-lg);
      padding: 20px;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.15s, transform 0.15s;
      transform: translateX(-50%) translateY(-4px);
      z-index: 200;
    }

    .dropdown-container:hover .dropdown-menu,
    .dropdown-container.active .dropdown-menu {
      opacity: 1;
      pointer-events: all;
      transform: translateX(-50%) translateY(0);
    }

    .mega-menu { width: 640px; display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 24px; }
    .resources-menu { width: 420px; display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }

    .dropdown-section-title {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--text-muted);
      margin-bottom: 10px;
    }

    .dropdown-item {
      display: flex;
      flex-direction: column;
      gap: 2px;
      padding: 8px 10px;
      border-radius: var(--radius-sm);
      transition: background 0.12s;
      cursor: pointer;
    }
    .dropdown-item:hover { background: var(--bg-hover); }

    .dropdown-item-title {
      font-size: 13px;
      font-weight: 600;
      color: var(--text-primary);
    }
    .dropdown-item-desc {
      font-size: 11.5px;
      color: var(--text-muted);
      line-height: 1.4;
    }

    /* ─── MAIN CONTAINER ──────────────────────────────────────── */
    .container {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ─── PAGE HEADER ─────────────────────────────────────────── */
    .page-header {
      padding: 56px 0 40px;
      border-bottom: 1px solid var(--border);
    }

    .page-header h1 {
      font-size: 42px;
      font-weight: 800;
      letter-spacing: -1.2px;
      line-height: 1.15;
      color: var(--text-primary);
      margin-bottom: 8px;
    }

    .page-header p {
      font-size: 15px;
      color: var(--text-muted);
      font-weight: 400;
    }

    /* ─── FILTERS ─────────────────────────────────────────────── */
    .filters-section {
      padding: 24px 0 0;
    }

    .filters-row {
      display: flex;
      align-items: center;
      gap: 12px;
      flex-wrap: wrap;
    }

    .filter-pills {
      display: flex;
      align-items: center;
      gap: 6px;
      flex-wrap: wrap;
      flex: 1;
    }

    .pill {
      font-family: var(--font);
      font-size: 13px;
      font-weight: 600;
      padding: 6px 14px;
      border-radius: 100px;
      border: 1.5px solid var(--border);
      background: transparent;
      color: var(--text-secondary);
      cursor: pointer;
      transition: all 0.15s;
      white-space: nowrap;
    }

    .pill:hover {
      border-color: var(--text-primary);
      color: var(--text-primary);
      background: var(--bg-hover);
    }

    .pill.active {
      background: var(--text-primary);
      border-color: var(--text-primary);
      color: #fff;
    }

    .search-wrap {
      position: relative;
      flex-shrink: 0;
    }

    .search-wrap svg {
      position: absolute;
      left: 12px;
      top: 50%;
      transform: translateY(-50%);
      width: 15px;
      height: 15px;
      color: var(--text-muted);
      pointer-events: none;
    }

    .search-input {
      font-family: var(--font);
      font-size: 13.5px;
      padding: 8px 14px 8px 36px;
      border: 1.5px solid var(--border);
      border-radius: var(--radius-sm);
      background: #fff;
      color: var(--text-primary);
      width: 220px;
      transition: border-color 0.15s, box-shadow 0.15s;
      outline: none;
    }

    .search-input:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 3px rgba(0,114,245,0.12);
    }

    .search-input::placeholder { color: var(--text-muted); }

    /* ─── FEATURED ARTICLES ───────────────────────────────────── */
    .section-label {
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--text-muted);
      margin-bottom: 20px;
      padding-top: 44px;
    }

    .featured-grid {
      display: grid;
      grid-template-columns: 1fr 1fr 1fr;
      gap: 20px;
      padding-bottom: 48px;
      border-bottom: 1px solid var(--border);
    }

    .featured-card {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      overflow: hidden;
      display: flex;
      flex-direction: column;
      transition: box-shadow 0.2s, transform 0.2s;
      cursor: pointer;
      position: relative;
    }

    .featured-card:hover {
      box-shadow: var(--shadow-lg);
      transform: translateY(-2px);
    }

    .featured-card::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 3px;
      background: linear-gradient(90deg, var(--accent), #38BDF8);
      opacity: 0;
      transition: opacity 0.2s;
    }

    .featured-card:hover::before { opacity: 1; }

    .featured-card-image {
      width: 100%;
      aspect-ratio: 16/9;
      background: linear-gradient(135deg, #0F172A 0%, #1E293B 60%, #0C4A6E 100%);
      position: relative;
      overflow: hidden;
      display: flex;
      align-items: flex-end;
    }

    .featured-card-image.theme-green {
      background: linear-gradient(135deg, #0F1F0F 0%, #14532D 60%, #15803D 100%);
    }

    .featured-card-image.theme-purple {
      background: linear-gradient(135deg, #1A0F2E 0%, #3B1F6B 60%, #6D28D9 100%);
    }

    .featured-img-overlay {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .featured-img-pattern {
      width: 100%;
      height: 100%;
      opacity: 0.15;
      background-image: radial-gradient(circle at 1px 1px, rgba(255,255,255,0.3) 1px, transparent 0);
      background-size: 24px 24px;
    }

    .featured-img-icon {
      position: absolute;
      width: 64px;
      height: 64px;
      background: rgba(255,255,255,0.1);
      border: 1px solid rgba(255,255,255,0.2);
      border-radius: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      backdrop-filter: blur(8px);
    }

    .featured-img-icon svg { width: 28px; height: 28px; color: #fff; }

    .featured-card-body {
      padding: 20px;
      display: flex;
      flex-direction: column;
      flex: 1;
      gap: 10px;
    }

    .featured-card-meta {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .tag {
      font-size: 11px;
      font-weight: 700;
      padding: 3px 9px;
      border-radius: 100px;
      letter-spacing: 0.04em;
    }

    .tag-blue { background: var(--accent-light); color: var(--accent); }
    .tag-green { background: #F0FDF4; color: #16A34A; }
    .tag-purple { background: #F5F3FF; color: #7C3AED; }
    .tag-orange { background: #FFF7ED; color: #C2410C; }
    .tag-gray { background: #F4F4F5; color: #52525B; }

    .meta-date {
      font-size: 12px;
      color: var(--text-muted);
      font-weight: 500;
    }

    .featured-card-title {
      font-size: 17px;
      font-weight: 700;
      line-height: 1.35;
      letter-spacing: -0.3px;
      color: var(--text-primary);
    }

    .featured-card-excerpt {
      font-size: 13.5px;
      color: var(--text-secondary);
      line-height: 1.6;
      flex: 1;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .featured-card-footer {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-top: 4px;
      padding-top: 14px;
      border-top: 1px solid var(--border);
    }

    .author-avatar {
      width: 28px;
      height: 28px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--accent), #38BDF8);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 11px;
      font-weight: 700;
      color: #fff;
      flex-shrink: 0;
    }

    .author-name {
      font-size: 12.5px;
      font-weight: 600;
      color: var(--text-secondary);
    }

    /* ─── STATS CALLOUT ───────────────────────────────────────── */
    .stats-callout {
      background: var(--navy);
      border-radius: var(--radius);
      padding: 28px 32px;
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 0;
      margin-bottom: 48px;
      position: relative;
      overflow: hidden;
    }

    .stats-callout::before {
      content: '';
      position: absolute;
      inset: 0;
      background-image: radial-gradient(circle at 2px 2px, rgba(255,255,255,0.06) 1px, transparent 0);
      background-size: 32px 32px;
    }

    .stats-callout-label {
      position: absolute;
      top: 20px;
      left: 32px;
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: rgba(255,255,255,0.4);
    }

    .stat-item {
      padding: 16px 24px;
      position: relative;
      z-index: 1;
    }

    .stat-item + .stat-item {
      border-left: 1px solid rgba(255,255,255,0.1);
    }

    .stat-number {
      font-size: 32px;
      font-weight: 800;
      letter-spacing: -1px;
      color: #fff;
      line-height: 1.1;
      margin-bottom: 4px;
    }

    .stat-number span { color: #38BDF8; }

    .stat-desc {
      font-size: 13px;
      color: rgba(255,255,255,0.5);
      line-height: 1.4;
      font-weight: 500;
    }

    /* ─── LATEST NEWS ─────────────────────────────────────────── */
    .latest-section { padding: 0 0 64px; }

    .section-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 24px;
    }

    .section-title {
      font-size: 20px;
      font-weight: 700;
      letter-spacing: -0.4px;
    }

    .posts-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
    }

    .post-card {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 20px;
      display: flex;
      flex-direction: column;
      gap: 10px;
      cursor: pointer;
      transition: box-shadow 0.18s, transform 0.18s, border-color 0.18s;
    }

    .post-card:hover {
      box-shadow: var(--shadow);
      transform: translateY(-1px);
      border-color: var(--border-strong);
    }

    .post-card-meta {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .post-card-title {
      font-size: 15px;
      font-weight: 700;
      line-height: 1.4;
      letter-spacing: -0.2px;
      color: var(--text-primary);
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .post-card-excerpt {
      font-size: 13px;
      color: var(--text-secondary);
      line-height: 1.6;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
      flex: 1;
    }

    .post-card-footer {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-top: 4px;
      padding-top: 12px;
      border-top: 1px solid var(--border);
    }

    .author-avatar-sm {
      width: 24px;
      height: 24px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 10px;
      font-weight: 700;
      color: #fff;
      flex-shrink: 0;
    }

    .post-card-author {
      font-size: 12px;
      font-weight: 600;
      color: var(--text-muted);
    }

    /* ─── NO RESULTS ──────────────────────────────────────────── */
    .no-results {
      grid-column: 1 / -1;
      display: none;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 64px 24px;
      text-align: center;
      gap: 12px;
    }

    .no-results.visible { display: flex; }

    .no-results-icon {
      width: 48px;
      height: 48px;
      background: var(--bg-hover);
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 4px;
    }

    .no-results-icon svg { width: 22px; height: 22px; color: var(--text-muted); }

    .no-results h3 {
      font-size: 16px;
      font-weight: 700;
      color: var(--text-primary);
    }

    .no-results p {
      font-size: 14px;
      color: var(--text-muted);
      max-width: 320px;
    }

    /* ─── SHOW MORE ───────────────────────────────────────────── */
    .show-more-wrap {
      display: flex;
      justify-content: center;
      padding: 32px 0 0;
    }

    .btn-show-more {
      font-family: var(--font);
      font-size: 14px;
      font-weight: 600;
      padding: 10px 28px;
      border-radius: var(--radius-sm);
      border: 1.5px solid var(--border-strong);
      background: #fff;
      color: var(--text-primary);
      cursor: pointer;
      transition: all 0.15s;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .btn-show-more:hover { background: var(--bg-hover); border-color: var(--text-primary); }
    .btn-show-more.hidden { display: none; }

    /* ─── CTA BANNER ──────────────────────────────────────────── */
    .cta-section {
      background: var(--navy);
      padding: 64px 0;
      position: relative;
      overflow: hidden;
    }

    .cta-section::before {
      content: '';
      position: absolute;
      inset: 0;
      background-image: radial-gradient(circle at 2px 2px, rgba(255,255,255,0.04) 1px, transparent 0);
      background-size: 40px 40px;
    }

    .cta-grid {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 48px;
      align-items: center;
    }

    .cta-main h2 {
      font-size: 32px;
      font-weight: 800;
      color: #fff;
      letter-spacing: -0.8px;
      line-height: 1.25;
      margin-bottom: 12px;
    }

    .cta-main h2 strong { color: #38BDF8; font-weight: 800; }

    .cta-main p {
      font-size: 15px;
      color: rgba(255,255,255,0.55);
      max-width: 480px;
    }

    .cta-actions {
      display: flex;
      gap: 10px;
      margin-top: 24px;
      flex-wrap: wrap;
    }

    .btn-cta-primary {
      font-family: var(--font);
      font-size: 14px;
      font-weight: 700;
      padding: 11px 24px;
      background: #fff;
      color: var(--navy);
      border: none;
      border-radius: var(--radius-sm);
      cursor: pointer;
      transition: all 0.15s;
    }

    .btn-cta-primary:hover { background: #E0F2FE; }

    .btn-cta-secondary {
      font-family: var(--font);
      font-size: 14px;
      font-weight: 600;
      padding: 10px 24px;
      background: transparent;
      color: rgba(255,255,255,0.8);
      border: 1.5px solid rgba(255,255,255,0.25);
      border-radius: var(--radius-sm);
      cursor: pointer;
      transition: all 0.15s;
    }

    .btn-cta-secondary:hover { background: rgba(255,255,255,0.08); border-color: rgba(255,255,255,0.5); color: #fff; }

    .cta-enterprise {
      background: rgba(255,255,255,0.05);
      border: 1px solid rgba(255,255,255,0.12);
      border-radius: var(--radius);
      padding: 24px;
      min-width: 240px;
    }

    .cta-enterprise-badge {
      font-size: 10px;
