    // Filter latest news cards
    allCards.forEach(card => {
      const title = card.dataset.title.toLowerCase();
      const tags = (card.dataset.tags || '').toLowerCase();
      const category = card.dataset.category || '';
      const isExtraCard = card.classList.contains('extra-card');

      const matchesCategory = activeCategory === 'all' ||
        normalizeCategory(category) === normalizeCategory(activeCategory) ||
        tags.includes(normalizeCategory(activeCategory));
      const matchesSearch = !query || title.includes(query);
      const isVisible = matchesCategory && matchesSearch;

      // Extra cards only show if revealed AND matching
      if (isExtraCard) {
        card.classList.toggle('hidden-card', !(hiddenCardsRevealed && isVisible));
      } else {
        card.classList.toggle('hidden-card', !isVisible);
      }

      if (isVisible && (!isExtraCard || hiddenCardsRevealed)) visibleCount++;
    });

    // Show/hide stats callout based on search/category
    const anyFeaturedVisible = [...featuredCards].some(c => !c.classList.contains('hidden-card'));
    if (statsCallout) {
      statsCallout.style.display = (activeCategory === 'all' || activeCategory === 'Engineering') && !query ? 'grid' : 'none';
    }

    // No results state
    noResults.classList.toggle('visible', visibleCount === 0);

    // Show more button visibility
    const hasHiddenExtra = [...allCards].some(c => c.classList.contains('extra-card') && !hiddenCardsRevealed);
    showMoreBtn.classList.toggle('hidden', hasHiddenExtra ? false : true || visibleCount === 0);
    if (query || activeCategory !== 'all') {
      showMoreBtn.classList.add('hidden');
    }
  }

  // Initial state — mark extra cards
  const allInitialCards = postsGrid.querySelectorAll('.post-card');
  allInitialCards.forEach((card, i) => {
    if (card.classList.contains('hidden-card')) {
      card.classList.add('extra-card');
    }
  });

  // ── PILL CLICKS ──────────────────────────────────────────────────
  filterPills.addEventListener('click', e => {
    const pill = e.target.closest('.pill');
    if (!pill) return;

    filterPills.querySelectorAll('.pill').forEach(p => p.classList.remove('active'));
    pill.classList.add('active');
    activeCategory = pill.dataset.category;
    filterPosts();
  });

  // ── SEARCH ───────────────────────────────────────────────────────
  let searchTimeout;
  searchInput.addEventListener('input', e => {
    clearTimeout(searchTimeout);
    searchTimeout = setTimeout(() => {
      searchQuery = e.target.value;
      filterPosts();
    }, 150);
  });

  // ── SHOW MORE ────────────────────────────────────────────────────
  showMoreBtn.addEventListener('click', () => {
    hiddenCardsRevealed = true;
    postsGrid.querySelectorAll('.post-card.extra-card').forEach(card => {
      card.classList.remove('hidden-card');
      card.style.animation = 'fadeIn 0.3s ease forwards';
    });
    showMoreBtn.classList.add('hidden');
  });

  // Initial filter run
  filterPosts();

  // ── FADE IN ANIMATION ────────────────────────────────────────────
  const style = document.createElement('style');
  style.textContent = `
    @keyframes fadeIn {
      from { opacity: 0; transform: translateY(8px); }
      to { opacity: 1; transform: translateY(0); }
    }
    .post-card { animation: fadeIn 0.4s ease forwards; }
    .featured-card { animation: fadeIn 0.5s ease forwards; }
    .stats-callout { animation: fadeIn 0.6s ease 0.1s both; }
  `;
  document.head.appendChild(style);
</script>
</body>
</html>

